-- Network, CRM, journeys, recommendations and gamification
create table if not exists public.journeys (id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null,description text,trigger_type text not null default 'manual',is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.journey_steps (id uuid primary key default gen_random_uuid(),journey_id uuid not null references public.journeys(id) on delete cascade,step_order integer not null check(step_order>=1),action_type text not null,delay_minutes integer not null default 0 check(delay_minutes>=0),config jsonb not null default '{}'::jsonb,unique(journey_id,step_order));
create table if not exists public.journey_enrollments (id uuid primary key default gen_random_uuid(),journey_id uuid not null references public.journeys(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,current_step integer not null default 1,status text not null default 'active' check(status in('active','completed','paused','cancelled')),next_run_at timestamptz,enrolled_at timestamptz not null default now(),completed_at timestamptz,unique(journey_id,user_id));
create table if not exists public.recommendations (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,entity_type text not null,entity_id uuid not null,score numeric(7,4) not null default 0,reason text,status text not null default 'active' check(status in('active','dismissed','consumed')),created_at timestamptz not null default now(),expires_at timestamptz);
create table if not exists public.gamification_points (user_id uuid primary key references auth.users(id) on delete cascade,total_points integer not null default 0 check(total_points>=0),level integer not null default 1 check(level>=1),updated_at timestamptz not null default now());
create table if not exists public.gamification_events (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,points integer not null,reason text not null,entity_type text,entity_id uuid,created_at timestamptz not null default now());
create index if not exists journeys_active_idx on public.journeys(is_active,created_at desc);create index if not exists journey_steps_journey_idx on public.journey_steps(journey_id,step_order);create index if not exists journey_enrollments_run_idx on public.journey_enrollments(status,next_run_at);create index if not exists recommendations_user_idx on public.recommendations(user_id,status,score desc);create index if not exists recommendations_entity_idx on public.recommendations(entity_type,entity_id);create index if not exists gamification_events_user_idx on public.gamification_events(user_id,created_at desc);
alter table public.journeys enable row level security;alter table public.journey_steps enable row level security;alter table public.journey_enrollments enable row level security;alter table public.recommendations enable row level security;alter table public.gamification_points enable row level security;alter table public.gamification_events enable row level security;
grant select,insert,update,delete on public.journeys to authenticated;grant select,insert,update,delete on public.journey_steps to authenticated;grant select,insert,update,delete on public.journey_enrollments to authenticated;grant select,insert,update,delete on public.recommendations to authenticated;grant select,insert,update,delete on public.gamification_points to authenticated;grant select,insert,update,delete on public.gamification_events to authenticated;
drop policy if exists journeys_staff_all on public.journeys;create policy journeys_staff_all on public.journeys for all to authenticated using(public.has_any_role(array['super_admin','crm_manager']::public.app_role[])) with check(public.has_any_role(array['super_admin','crm_manager']::public.app_role[]));
drop policy if exists journey_steps_staff_all on public.journey_steps;create policy journey_steps_staff_all on public.journey_steps for all to authenticated using(public.has_any_role(array['super_admin','crm_manager']::public.app_role[])) with check(public.has_any_role(array['super_admin','crm_manager']::public.app_role[]));
drop policy if exists journey_enrollments_self on public.journey_enrollments;create policy journey_enrollments_self on public.journey_enrollments for select to authenticated using(user_id=(select auth.uid()));
drop policy if exists journey_enrollments_staff on public.journey_enrollments;create policy journey_enrollments_staff on public.journey_enrollments for all to authenticated using(public.has_any_role(array['super_admin','crm_manager']::public.app_role[])) with check(public.has_any_role(array['super_admin','crm_manager']::public.app_role[]));
drop policy if exists recommendations_self on public.recommendations;create policy recommendations_self on public.recommendations for select to authenticated using(user_id=(select auth.uid()));
drop policy if exists recommendations_self_update on public.recommendations;create policy recommendations_self_update on public.recommendations for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
drop policy if exists recommendations_staff on public.recommendations;create policy recommendations_staff on public.recommendations for all to authenticated using(public.has_any_role(array['super_admin','crm_manager','program_manager']::public.app_role[])) with check(public.has_any_role(array['super_admin','crm_manager','program_manager']::public.app_role[]));
drop policy if exists gamification_points_self on public.gamification_points;create policy gamification_points_self on public.gamification_points for select to authenticated using(user_id=(select auth.uid()));
drop policy if exists gamification_points_staff on public.gamification_points;create policy gamification_points_staff on public.gamification_points for select to authenticated using(public.has_any_role(array['super_admin','crm_manager','auditor']::public.app_role[]));
drop policy if exists gamification_events_self on public.gamification_events;create policy gamification_events_self on public.gamification_events for select to authenticated using(user_id=(select auth.uid()));
drop policy if exists gamification_events_staff on public.gamification_events;create policy gamification_events_staff on public.gamification_events for select to authenticated using(public.has_any_role(array['super_admin','crm_manager','auditor']::public.app_role[]));
drop policy if exists engagement_self_insert on public.engagement_events;create policy engagement_self_insert on public.engagement_events for insert to authenticated with check(user_id=(select auth.uid()));
drop policy if exists engagement_self_read on public.engagement_events;create policy engagement_self_read on public.engagement_events for select to authenticated using(user_id=(select auth.uid()));
drop policy if exists engagement_staff_read on public.engagement_events;create policy engagement_staff_read on public.engagement_events for select to authenticated using(public.has_any_role(array['super_admin','crm_manager','regional_manager','auditor']::public.app_role[]));
create or replace function private.award_points(p_points integer,p_reason text,p_entity_type text default null,p_entity_id uuid default null) returns public.gamification_points language plpgsql security definer set search_path=public,pg_temp as $$ declare v_user uuid:=auth.uid(); v_points public.gamification_points%rowtype; begin if v_user is null then raise exception 'authentication_required'; end if; if p_points is null or p_points=0 or abs(p_points)>1000 then raise exception 'invalid_points'; end if; insert into public.gamification_points(user_id,total_points,level) values(v_user,greatest(p_points,0),greatest(1,floor(greatest(p_points,0)/100)+1)) on conflict(user_id) do update set total_points=greatest(0,public.gamification_points.total_points+p_points),level=greatest(1,floor(greatest(0,public.gamification_points.total_points+p_points)/100)+1),updated_at=now() returning * into v_points; insert into public.gamification_events(user_id,points,reason,entity_type,entity_id) values(v_user,p_points,p_reason,p_entity_type,p_entity_id); return v_points; end; $$;
revoke all on function private.award_points(integer,text,text,uuid) from public,anon,authenticated;
drop function if exists public.award_points(integer,text,text,uuid);
create or replace function public.award_points(p_points integer,p_reason text,p_entity_type text default null,p_entity_id uuid default null) returns public.gamification_points language sql security invoker set search_path=public,pg_temp as $$ select * from private.award_points(p_points,p_reason,p_entity_type,p_entity_id); $$;
revoke all on function public.award_points(integer,text,text,uuid) from public,anon;grant execute on function public.award_points(integer,text,text,uuid) to authenticated;